def icon(name: str, size: int = 20) -> str:
    """Return an inline, decorative Feather SVG (default 2px stroke, round caps)."""
    return (
        f'<svg class="fi" xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" '
        'viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" '
        f'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{_PATHS[name]}</svg>'
    )
